<template id="item-template"><div class="item-row grid grid-cols-12 gap-3 items-end bg-slate-50 p-4 rounded-xl border"><div class="col-span-5"><label>Produk</label><select name="items[__INDEX__][product_id]" required class="product-select w-full rounded-xl border p-3" onchange="updatePrice(this)"><option value="">Pilih Produk</option>@foreach($products as $prod)<option value="{{ $prod->id }}" data-price="{{ $prod->buy_price }}">{{ $prod->name }} (Harga Beli: Rp {{ number_format($prod->buy_price,0,',','.') }})</option>@endforeach</select></div><div class="col-span-2"><label>Qty</label><input type="number" name="items[__INDEX__][quantity]" value="1" min="1" required class="w-full rounded-xl border p-3"></div><div class="col-span-3"><label>Harga Beli</label><input type="number" name="items[__INDEX__][price]" value="0" min="0" required class="price-input w-full rounded-xl border p-3 font-semibold text-indigo-600"></div><div class="col-span-2"><button type="button" onclick="removeItem(this)" class="w-full px-3 py-3 bg-red-50 text-red-600 rounded-xl">Hapus</button></div></div></template>
<script>let itemIndex=0;function addItem(){let t=document.getElementById('item-template').innerHTML.replaceAll('__INDEX__',itemIndex++);document.getElementById('items-container').insertAdjacentHTML('beforeend',t)}function removeItem(btn){btn.closest('.item-row').remove();if(!document.querySelector('.item-row'))addItem()}function updatePrice(select){select.closest('.item-row').querySelector('.price-input').value=select.options[select.selectedIndex].dataset.price||0}addItem();</script>
